// NewOTLPExporter is an ExporterFactory for OTLP backends: ProtocolGRPC uses
// otlptracegrpc, ProtocolHTTPProtobuf and the empty protocol use otlptracehttp.
// Endpoint, headers, compression and TLS come from cfg; an http:// endpoint means
// plaintext. ProtocolNative is rejected (the service provides that exporter).
func NewOTLPExporter(ctx context.Context, cfg TracingConfig) (sdktrace.SpanExporter, error) {
	cfg = cfg.WithDefaults()
	tlsCfg, err := buildTLS(cfg.TLS)
	if err != nil {
		return nil, err
	}
	secure := strings.HasPrefix(cfg.Endpoint, "https://")
	switch cfg.Protocol {
	case ProtocolGRPC:
		opts := []otlptracegrpc.Option{}
		if cfg.Endpoint != "" {
			opts = append(opts, otlptracegrpc.WithEndpointURL(cfg.Endpoint))
			if secure {
				opts = append(opts, otlptracegrpc.WithTLSCredentials(credentials.NewTLS(tlsCfg)))
			}
		}
		if len(cfg.Headers) > 0 {
			opts = append(opts, otlptracegrpc.WithHeaders(cfg.Headers))
		}
		if cfg.Compression == CompressionGzip {
			opts = append(opts, otlptracegrpc.WithCompressor("gzip"))
		}
		return otlptracegrpc.New(ctx, opts...)
	case ProtocolNative:
		return nil, ConfigError("tracing: protocol native needs the service's own exporter")
	}
	opts := []otlptracehttp.Option{}
	if cfg.Endpoint != "" {
		opts = append(opts, otlptracehttp.WithEndpointURL(otlpHTTPTracesURL(cfg.Endpoint)))
		if secure {
			opts = append(opts, otlptracehttp.WithTLSClientConfig(tlsCfg))
		}
	}
	if len(cfg.Headers) > 0 {
		opts = append(opts, otlptracehttp.WithHeaders(cfg.Headers))
	}
	if cfg.Compression == CompressionGzip {
		opts = append(opts, otlptracehttp.WithCompression(otlptracehttp.GzipCompression))
	} else {
		opts = append(opts, otlptracehttp.WithCompression(otlptracehttp.NoCompression))
	}
	return otlptracehttp.New(ctx, opts...)
}

// otlpHTTPTracesURL appends /v1/traces to an endpoint without a path.
func otlpHTTPTracesURL(endpoint string) string {
	u, err := url.Parse(endpoint)
	if err != nil || (u.Path != "" && u.Path != "/") {
		return endpoint
	}
	u.Path = "/v1/traces"
	return u.String()
}

